import{_ as a,a as s,c as t,ac as o}from"./chunks/framework.BSuaGltH.js";const g=JSON.parse('{"title":"第一册：英语初阶 · 综合复习与自测 · 第39–45课","description":"全册逐课覆盖的原创练习、折叠答案和表达迁移任务。","frontmatter":{"title":"第一册：英语初阶 · 综合复习与自测 · 第39–45课","description":"全册逐课覆盖的原创练习、折叠答案和表达迁移任务。","splitFrom":"life/english/new-concept/book-1/review.md","showdocs":{"topics":[{"id":"english","title":"英语","link":"/topics/english/"}],"kind":"读写与对话练习","scope":"general","audience":"general","group":"学习与记录","seriesTitle":"第一册：英语初阶 · 综合复习与自测","summary":"全册逐课覆盖的原创练习、折叠答案和表达迁移任务。","status":"active","related":[{"title":"程序员英语 01：学习路线与能力自测","link":"/life/english/programmer/overview","kind":"路线与能力起点","scope":"general","audience":"general"},{"title":"程序员英语 02：技术词汇与句子骨架","link":"/life/english/programmer/vocabulary","kind":"路线与能力起点","scope":"general","audience":"general"},{"title":"程序员英语 03：读懂文档中的条件与约束","link":"/life/english/programmer/reading-docs","kind":"路线与能力起点","scope":"general","audience":"general"},{"title":"程序员英语 04：读报错、搜索与求助","link":"/life/english/programmer/errors-search","kind":"路线与能力起点","scope":"general","audience":"general"},{"title":"程序员英语 05：写 Issue、Commit 与 PR","link":"/life/english/programmer/issue-pr","kind":"路线与能力起点","scope":"general","audience":"general"}],"prev":{"text":"第一册：英语初阶 · 综合复习与自测 · 第32–38课","link":"/life/english/new-concept/book-1/review-part-05"},"next":{"text":"第一册：英语初阶 · 综合复习与自测 · 第46–52课","link":"/life/english/new-concept/book-1/review-part-07"}},"layout":"ReadingPage","sidebar":false,"aside":false,"prev":{"text":"第一册：英语初阶 · 综合复习与自测 · 第32–38课","link":"/life/english/new-concept/book-1/review-part-05"},"next":{"text":"第一册：英语初阶 · 综合复习与自测 · 第46–52课","link":"/life/english/new-concept/book-1/review-part-07"}},"headers":[],"relativePath":"life/english/new-concept/book-1/review-part-06.md","filePath":"life/english/new-concept/book-1/review-part-06.md"}'),n={name:"life/english/new-concept/book-1/review-part-06.md"};function r(i,e,l,p,c,h){return s(),t("div",null,[...e[0]||(e[0]=[o('<h1 id="第一册-英语初阶-·-综合复习与自测-·-第39–45课" tabindex="-1">第一册：英语初阶 · 综合复习与自测 · 第39–45课 <a class="header-anchor" href="#第一册-英语初阶-·-综合复习与自测-·-第39–45课" aria-label="Permalink to &quot;第一册：英语初阶 · 综合复习与自测 · 第39–45课&quot;">​</a></h1><p><a href="/life/english/new-concept/book-1/review">返回分篇目录</a></p><p><a href="/life/english/new-concept/book-1/overview">本册介绍</a> · <a href="/life/english/new-concept/book-1/contents">全册课程目录</a> · <a href="/life/english/new-concept/book-1/grammar">全册语法总结</a> · <a href="/life/english/new-concept/book-1/vocabulary">全册单词总结</a> · <a href="/life/english/new-concept/book-1/phrases">全册短语与句型</a> · <a href="/life/english/new-concept/book-1/mistakes">全册易错点</a> · <a href="/life/english/new-concept/book-1/review">综合复习与自测</a></p><p>先独立作答，再展开答案。下列原创题从相应课时选取，覆盖本范围每一课；错题请回到课时讲解解释错误原因，再替换一个条件重做。</p><h2 id="lesson-39-·-否定祈使句与宾语代词" tabindex="-1">Lesson 39 · 否定祈使句与宾语代词 <a class="header-anchor" href="#lesson-39-·-否定祈使句与宾语代词" aria-label="Permalink to &quot;Lesson 39 · 否定祈使句与宾语代词 {#lesson-39-·-否定祈使句与宾语代词}&quot;">​</a></h2><p><strong>阅读材料（本站原创）：</strong> Do not put the wet box on the bed.</p><h3 id="练习-1-38" tabindex="-1">练习 1 <a class="header-anchor" href="#练习-1-38" aria-label="Permalink to &quot;练习 1 {#练习-1-38}&quot;">​</a></h3><p>补否定助动词：___ put the box there.</p><details class="details custom-block"><summary>参考答案与解析</summary><p><strong>答案：</strong> Don&#39;t</p><p><strong>解析：</strong> 按本课规则判断：否定祈使句用 Don&#39;t + 动词原形，可提醒对方不要做某事。动词后用 it/them 指代物品：lift it、move them。计划用 be going to + 动词原形；介词 on 与 onto 的差异在于位置和移动到表面。给出指令时先说明对象，再用代词承接，避免不知道 it 指什么。</p></details><p><strong>表达迁移：</strong> 围绕“搬动物品时提醒并说明打算”写两至三句，再读给同伴听。至少使用一次否定祈使句与宾语代词，改变一个人物或对象后再说一遍。</p><details class="details custom-block"><summary>表达参考与点评</summary><p>Do not put the wet box on the bed. We are going to carry it upstairs.</p><p>Do not 加 put 原形构成否定祈使句；the wet box 为对象，on the bed 为禁止放置的位置。 We are going to carry 表打算；it 指前文物品，作 carry 的宾语；upstairs 是方向副词，不加 to。</p></details><p><a href="/life/english/new-concept/book-1/unit-02/lesson-039">回看本课</a></p><h2 id="lesson-40-·-否定祈使句与宾语代词" tabindex="-1">Lesson 40 · 否定祈使句与宾语代词 <a class="header-anchor" href="#lesson-40-·-否定祈使句与宾语代词" aria-label="Permalink to &quot;Lesson 40 · 否定祈使句与宾语代词 {#lesson-40-·-否定祈使句与宾语代词}&quot;">​</a></h2><p><strong>阅读材料（本站原创）：</strong> We are going to carry it upstairs.</p><h3 id="练习-1-39" tabindex="-1">练习 1 <a class="header-anchor" href="#练习-1-39" aria-label="Permalink to &quot;练习 1 {#练习-1-39}&quot;">​</a></h3><p>填代词：the box → carry ___.</p><details class="details custom-block"><summary>参考答案与解析</summary><p><strong>答案：</strong> it</p><p><strong>解析：</strong> 按本课规则判断：否定祈使句用 Don&#39;t + 动词原形，可提醒对方不要做某事。动词后用 it/them 指代物品：lift it、move them。计划用 be going to + 动词原形；介词 on 与 onto 的差异在于位置和移动到表面。给出指令时先说明对象，再用代词承接，避免不知道 it 指什么。</p></details><p><strong>表达迁移：</strong> 围绕“搬动物品时提醒并说明打算”写两至三句，再读给同伴听。至少使用一次否定祈使句与宾语代词，改变一个人物或对象后再说一遍。</p><details class="details custom-block"><summary>表达参考与点评</summary><p>We are going to carry it upstairs. Do not put the wet box on the bed.</p><p>We are going to carry 表打算；it 指前文物品，作 carry 的宾语；upstairs 是方向副词，不加 to。 Do not 加 put 原形构成否定祈使句；the wet box 为对象，on the bed 为禁止放置的位置。</p></details><p><a href="/life/english/new-concept/book-1/unit-02/lesson-040">回看本课</a></p><h2 id="lesson-41-·-不可数名词与量词" tabindex="-1">Lesson 41 · 不可数名词与量词 <a class="header-anchor" href="#lesson-41-·-不可数名词与量词" aria-label="Permalink to &quot;Lesson 41 · 不可数名词与量词 {#lesson-41-·-不可数名词与量词}&quot;">​</a></h2><p><strong>阅读材料（本站原创）：</strong> There is a bottle of juice in my bag.</p><h3 id="练习-1-40" tabindex="-1">练习 1 <a class="header-anchor" href="#练习-1-40" aria-label="Permalink to &quot;练习 1 {#练习-1-40}&quot;">​</a></h3><p>把 a bottle of juice 改为“两瓶果汁”。</p><details class="details custom-block"><summary>参考答案与解析</summary><p><strong>答案：</strong> two bottles of juice</p><p><strong>解析：</strong> 按本课规则判断：不可数名词通常不直接与 a/an 或数词连用，可用 a bottle of water、a piece of paper 表示可计量单位。计数时改变单位名词，如 two bottles of water，water 不加 s。there is 与不可数名词配合。some 常见于肯定句，any 常见于疑问和否定句，但请求和期待肯定的问句也可用 some。</p></details><p><strong>表达迁移：</strong> 围绕“说明包内数量与不可数物品”写两至三句，再读给同伴听。至少使用一次不可数名词与量词，改变一个人物或对象后再说一遍。</p><details class="details custom-block"><summary>表达参考与点评</summary><p>There is a bottle of juice in my bag. Is there any paper in the drawer?</p><p>There is 的单数依据是数量核心 a bottle；of juice 说明瓶中内容，in my bag 是地点。 Is there 询问存在，paper 为物质义不可数名词，any 表不确定数量；in the drawer 说明搜索范围。</p></details><p><a href="/life/english/new-concept/book-1/unit-02/lesson-041">回看本课</a></p><h2 id="lesson-42-·-不可数名词与量词" tabindex="-1">Lesson 42 · 不可数名词与量词 <a class="header-anchor" href="#lesson-42-·-不可数名词与量词" aria-label="Permalink to &quot;Lesson 42 · 不可数名词与量词 {#lesson-42-·-不可数名词与量词}&quot;">​</a></h2><p><strong>阅读材料（本站原创）：</strong> Is there any paper in the drawer?</p><h3 id="练习-1-41" tabindex="-1">练习 1 <a class="header-anchor" href="#练习-1-41" aria-label="Permalink to &quot;练习 1 {#练习-1-41}&quot;">​</a></h3><p>填 be：There ___ some water.</p><details class="details custom-block"><summary>参考答案与解析</summary><p><strong>答案：</strong> is</p><p><strong>解析：</strong> 按本课规则判断：不可数名词通常不直接与 a/an 或数词连用，可用 a bottle of water、a piece of paper 表示可计量单位。计数时改变单位名词，如 two bottles of water，water 不加 s。there is 与不可数名词配合。some 常见于肯定句，any 常见于疑问和否定句，但请求和期待肯定的问句也可用 some。</p></details><p><strong>表达迁移：</strong> 围绕“说明包内数量与不可数物品”写两至三句，再读给同伴听。至少使用一次不可数名词与量词，改变一个人物或对象后再说一遍。</p><details class="details custom-block"><summary>表达参考与点评</summary><p>Is there any paper in the drawer? There is a bottle of juice in my bag.</p><p>Is there 询问存在，paper 为物质义不可数名词，any 表不确定数量；in the drawer 说明搜索范围。 There is 的单数依据是数量核心 a bottle；of juice 说明瓶中内容，in my bag 是地点。</p></details><p><a href="/life/english/new-concept/book-1/unit-02/lesson-042">回看本课</a></p><h2 id="lesson-43-·-some-any-与存在句疑问" tabindex="-1">Lesson 43 · some/any 与存在句疑问 <a class="header-anchor" href="#lesson-43-·-some-any-与存在句疑问" aria-label="Permalink to &quot;Lesson 43 · some/any 与存在句疑问 {#lesson-43-·-some-any-与存在句疑问}&quot;">​</a></h2><p><strong>阅读材料（本站原创）：</strong> Are there any clean mugs in the cupboard?</p><h3 id="练习-1-42" tabindex="-1">练习 1 <a class="header-anchor" href="#练习-1-42" aria-label="Permalink to &quot;练习 1 {#练习-1-42}&quot;">​</a></h3><p>填 be：___ there any clean mugs?</p><details class="details custom-block"><summary>参考答案与解析</summary><p><strong>答案：</strong> Are</p><p><strong>解析：</strong> 按本课规则判断：提问某处有没有东西时，将 there be 中的 be 提前：Is there ...? / Are there ...?。不可数名词和单数用 is，复数用 are。any 常用于中性询问及否定；some 可以用于提供食物或期待肯定回答的请求。简短回答用 there is/are，不用 it is/they are 来替代存在句的 there。</p></details><p><strong>表达迁移：</strong> 围绕“检查厨房还有哪些食材”写两至三句，再读给同伴听。至少使用一次some/any 与存在句疑问，改变一个人物或对象后再说一遍。</p><details class="details custom-block"><summary>表达参考与点评</summary><p>Are there any clean mugs in the cupboard? There is not any milk in the fridge.</p><p>Mugs 为复数，所以用 Are there；any 在中性疑问中表示有没有一些，clean 修饰 mugs。 Milk 为不可数名词，所以用 is；not any 表数量为零。in the fridge 限定不存在牛奶的位置。</p></details><p><a href="/life/english/new-concept/book-1/unit-02/lesson-043">回看本课</a></p><h2 id="lesson-44-·-some-any-与存在句疑问" tabindex="-1">Lesson 44 · some/any 与存在句疑问 <a class="header-anchor" href="#lesson-44-·-some-any-与存在句疑问" aria-label="Permalink to &quot;Lesson 44 · some/any 与存在句疑问 {#lesson-44-·-some-any-与存在句疑问}&quot;">​</a></h2><p><strong>阅读材料（本站原创）：</strong> There is not any milk in the fridge.</p><h3 id="练习-1-43" tabindex="-1">练习 1 <a class="header-anchor" href="#练习-1-43" aria-label="Permalink to &quot;练习 1 {#练习-1-43}&quot;">​</a></h3><p>补否定句：There is not ___ milk.</p><details class="details custom-block"><summary>参考答案与解析</summary><p><strong>答案：</strong> any</p><p><strong>解析：</strong> 按本课规则判断：提问某处有没有东西时，将 there be 中的 be 提前：Is there ...? / Are there ...?。不可数名词和单数用 is，复数用 are。any 常用于中性询问及否定；some 可以用于提供食物或期待肯定回答的请求。简短回答用 there is/are，不用 it is/they are 来替代存在句的 there。</p></details><p><strong>表达迁移：</strong> 围绕“检查厨房还有哪些食材”写两至三句，再读给同伴听。至少使用一次some/any 与存在句疑问，改变一个人物或对象后再说一遍。</p><details class="details custom-block"><summary>表达参考与点评</summary><p>There is not any milk in the fridge. Are there any clean mugs in the cupboard?</p><p>Milk 为不可数名词，所以用 is；not any 表数量为零。in the fridge 限定不存在牛奶的位置。 Mugs 为复数，所以用 Are there；any 在中性疑问中表示有没有一些，clean 修饰 mugs。</p></details><p><a href="/life/english/new-concept/book-1/unit-02/lesson-044">回看本课</a></p><h2 id="lesson-45-·-can-表能力" tabindex="-1">Lesson 45 · can 表能力 <a class="header-anchor" href="#lesson-45-·-can-表能力" aria-label="Permalink to &quot;Lesson 45 · can 表能力 {#lesson-45-·-can-表能力}&quot;">​</a></h2><p><strong>阅读材料（本站原创）：</strong> My colleague can translate this message.</p><h3 id="练习-1-44" tabindex="-1">练习 1 <a class="header-anchor" href="#练习-1-44" aria-label="Permalink to &quot;练习 1 {#练习-1-44}&quot;">​</a></h3><p>填动词：She can ___ (translate) this message.</p><details class="details custom-block"><summary>参考答案与解析</summary><p><strong>答案：</strong> translate</p><p><strong>解析：</strong> 按本课规则判断：can 后接动词原形，对所有人称保持 can，不增加 s。否定为 cannot 或 can&#39;t；问句把 can 放在主语前，不另加 do。can 表能力时说明能否完成动作，不等于动作正在发生。副词可说明做得怎样，如 type quickly；形容词常用于描述人或物。</p></details><p><strong>表达迁移：</strong> 围绕“说明能够完成的工作”写两至三句，再读给同伴听。至少使用一次can 表能力，改变一个人物或对象后再说一遍。</p><details class="details custom-block"><summary>表达参考与点评</summary><p>My colleague can translate this message. Can you print the report today?</p><p>My colleague 是第三人称单数，但 can 不加 s；translate 用原形，this message 为宾语。 Can 前置形成问句，you 为主语，print 为原形；today 说明希望完成任务的时间。</p></details><p><a href="/life/english/new-concept/book-1/unit-02/lesson-045">回看本课</a></p>',60)])])}const d=a(n,[["render",r]]);export{g as __pageData,d as default};
